legionaryUpgrade.effect:
t=>{
  if(S.civ?.[t]!==40)return;
  const old=U.mil.hp+(S.tech[t]?.hpb?.mil||0);
  const updated=U.legionary.hp+(S.tech[t]?.hpb?.legionary||0);
  for(const u of S.us)if(u?.t===t&&u.k==='mil'&&u.hp>0){
   u.k='legionary';u.hp=Math.min(updated,Math.max(1,u.hp+updated-old));
  }
  for(const b of S.bs)if(b?.t===t&&Array.isArray(b.q))for(const q of b.q)if(q?.k==='mil'){
   q.k='legionary';q.t=Math.min(q.t,U.legionary.t);
  }
 }

ut34.effect:
t=>{
  // Grant up to five real Serjeants per owned Town Centre, at most 25,
  // respecting current population limits and open spawn cells.
  let summoned=0;
  for(const tc of S.bs)if(tc.t===t&&tc.k==='tc'&&tc.hp>0&&tc.done){
   for(let i=0;i<5&&summoned<25;i++){
    if(livePopulation(t)>=capOf(t))return;
    const pos=spawnPos(tc);if(!pos)break;
    addU(t,'serjeant',pos[0],pos[1]);summoned++;
   }
  }
 }

ut41p.effect:
t=>{
